@code {
    private List<Shipment> shipments = [];
    private bool isLoading = true;
    private bool showForm;
    private bool isSaving;
    private Shipment editingShipment = new();
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;
    private string sortColumn = "EstimatedDelivery";
    private bool sortAscending = true;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        isLoading = false;
    }

    private IEnumerable<Shipment> FilteredShipments
    {
        get
        {
            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(filterText))
                result = result.Where(s => s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                    || s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                    || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase));

            if (!string.IsNullOrWhiteSpace(statusFilter))
                result = result.Where(s => s.Status == statusFilter);

            result = sortColumn switch
            {
                "TrackingNumber" => sortAscending ? result.OrderBy(s => s.TrackingNumber) : result.OrderByDescending(s => s.TrackingNumber),
                "Status" => sortAscending ? result.OrderBy(s => s.Status) : result.OrderByDescending(s => s.Status),
                "Origin" => sortAscending ? result.OrderBy(s => s.Origin) : result.OrderByDescending(s => s.Origin),
                "Destination" => sortAscending ? result.OrderBy(s => s.Destination) : result.OrderByDescending(s => s.Destination),
                "EstimatedDelivery" => sortAscending ? result.OrderBy(s => s.EstimatedDelivery) : result.OrderByDescending(s => s.EstimatedDelivery),
                _ => result
            };

            return result;
        }
    }

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private string SortIndicator(string column)
    {
        if (sortColumn != column) return "";
        return sortAscending ? "▲" : "▼";
    }

    private void ShowCreateForm()
    {
        editingShipment = new Shipment
        {
            ShippedDate = DateTime.Today,
            EstimatedDelivery = DateTime.Today.AddDays(5),
            Status = "Pending"
        };
        showForm = true;
    }

    private void EditShipment(Shipment shipment)
    {
        editingShipment = new Shipment
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Status = shipment.Status,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            CustomerEmail = shipment.CustomerEmail,
            ShippedDate = shipment.ShippedDate,
            EstimatedDelivery = shipment.EstimatedDelivery,
            Notes = shipment.Notes
        };
        showForm = true;
    }

    private async Task SaveShipment()
    {
        isSaving = true;
        if (editingShipment.Id == 0)
            await ShipmentService.CreateShipmentAsync(editingShipment);
        else
            await ShipmentService.UpdateShipmentAsync(editingShipment);

        showForm = false;
        isSaving = false;
        await LoadShipments();
    }

    private void CloseForm() => showForm = false;

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-info",
        "Pending" => "bg-warning text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

