@page "/shipments"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher - All Shipments</PageTitle>

<h1>Shipments</h1>
<p>Manage and monitor all shipments.</p>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            <option value="Pending">Pending</option>
            <option value="In Transit">In Transit</option>
            <option value="Out for Delivery">Out for Delivery</option>
            <option value="Delivered">Delivered</option>
            <option value="Cancelled">Cancelled</option>
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-success" @onclick="ShowCreateForm">
            + New Shipment
        </button>
    </div>
</div>

@if (isLoading)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th @onclick='() => SortBy("TrackingNumber")' style="cursor:pointer">Tracking # @SortIndicator("TrackingNumber")</th>
                    <th @onclick='() => SortBy("Status")' style="cursor:pointer">Status @SortIndicator("Status")</th>
                    <th @onclick='() => SortBy("Origin")' style="cursor:pointer">Origin @SortIndicator("Origin")</th>
                    <th @onclick='() => SortBy("Destination")' style="cursor:pointer">Destination @SortIndicator("Destination")</th>
                    <th @onclick='() => SortBy("EstimatedDelivery")' style="cursor:pointer">Est. Delivery @SortIndicator("EstimatedDelivery")</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => EditShipment(shipment)">Edit</button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@if (showForm)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5)">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">@(editingShipment.Id == 0 ? "New Shipment" : "Edit Shipment")</h5>
                    <button type="button" class="btn-close" @onclick="CloseForm"></button>
                </div>
                <div class="modal-body">
                    <EditForm Model="editingShipment" OnValidSubmit="SaveShipment" FormName="shipmentForm">
                        <DataAnnotationsValidator />
                        <div class="mb-3">
                            <label class="form-label">Tracking Number</label>
                            <InputText class="form-control" @bind-Value="editingShipment.TrackingNumber" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Status</label>
                            <InputSelect class="form-select" @bind-Value="editingShipment.Status">
                                <option value="Pending">Pending</option>
                                <option value="In Transit">In Transit</option>
                                <option value="Out for Delivery">Out for Delivery</option>
                                <option value="Delivered">Delivered</option>
                                <option value="Cancelled">Cancelled</option>
                            </InputSelect>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Origin</label>
                            <InputText class="form-control" @bind-Value="editingShipment.Origin" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Destination</label>
                            <InputText class="form-control" @bind-Value="editingShipment.Destination" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Customer Email</label>
                            <InputText class="form-control" @bind-Value="editingShipment.CustomerEmail" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Shipped Date</label>
                            <InputDate class="form-control" @bind-Value="editingShipment.ShippedDate" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Estimated Delivery</label>
                            <InputDate class="form-control" @bind-Value="editingShipment.EstimatedDelivery" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Notes</label>
                            <InputTextArea class="form-control" @bind-Value="editingShipment.Notes" />
                        </div>
                        <button type="submit" class="btn btn-primary" disabled="@isSaving">
                            @(isSaving ? "Saving..." : "Save")
                        </button>
                    </EditForm>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private List<Shipment> shipments = [];
    private bool isLoading = true;
    private bool showForm;
    private bool isSaving;
    private Shipment editingShipment = new();
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;
    private string sortColumn = "EstimatedDelivery";
    private bool sortAscending = true;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        isLoading = false;
    }

    private IEnumerable<Shipment> FilteredShipments
    {
        get
        {
            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(filterText))
                result = result.Where(s => s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                    || s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                    || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase));

            if (!string.IsNullOrWhiteSpace(statusFilter))
                result = result.Where(s => s.Status == statusFilter);

            result = sortColumn switch
            {
                "TrackingNumber" => sortAscending ? result.OrderBy(s => s.TrackingNumber) : result.OrderByDescending(s => s.TrackingNumber),
                "Status" => sortAscending ? result.OrderBy(s => s.Status) : result.OrderByDescending(s => s.Status),
                "Origin" => sortAscending ? result.OrderBy(s => s.Origin) : result.OrderByDescending(s => s.Origin),
                "Destination" => sortAscending ? result.OrderBy(s => s.Destination) : result.OrderByDescending(s => s.Destination),
                "EstimatedDelivery" => sortAscending ? result.OrderBy(s => s.EstimatedDelivery) : result.OrderByDescending(s => s.EstimatedDelivery),
                _ => result
            };

            return result;
        }
    }

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private string SortIndicator(string column)
    {
        if (sortColumn != column) return "";
        return sortAscending ? "▲" : "▼";
    }

    private void ShowCreateForm()
    {
        editingShipment = new Shipment
        {
            ShippedDate = DateTime.Today,
            EstimatedDelivery = DateTime.Today.AddDays(5),
            Status = "Pending"
        };
        showForm = true;
    }

    private void EditShipment(Shipment shipment)
    {
        editingShipment = new Shipment
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Status = shipment.Status,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            CustomerEmail = shipment.CustomerEmail,
            ShippedDate = shipment.ShippedDate,
            EstimatedDelivery = shipment.EstimatedDelivery,
            Notes = shipment.Notes
        };
        showForm = true;
    }

    private async Task SaveShipment()
    {
        isSaving = true;
        if (editingShipment.Id == 0)
            await ShipmentService.CreateShipmentAsync(editingShipment);
        else
            await ShipmentService.UpdateShipmentAsync(editingShipment);

        showForm = false;
        isSaving = false;
        await LoadShipments();
    }

    private void CloseForm() => showForm = false;

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-info",
        "Pending" => "bg-warning text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

