                        <dd class="col-sm-8">@foundShipment.Destination</dd>

                        <dt class="col-sm-4">Shipped Date</dt>
                        <dd class="col-sm-8">@foundShipment.ShippedDate.ToString("MMM dd, yyyy")</dd>

                        <dt class="col-sm-4">Estimated Delivery</dt>
                        <dd class="col-sm-8"><strong>@foundShipment.EstimatedDelivery.ToString("MMM dd, yyyy")</strong></dd>

                        @if (!string.IsNullOrEmpty(foundShipment.Notes))
                        {
                            <dt class="col-sm-4">Notes</dt>
                            <dd class="col-sm-8">@foundShipment.Notes</dd>
                        }
                    </dl>
                </div>
            </div>
        }
        else
        {
            <div class="alert alert-warning mt-4">
                No shipment found with tracking number "<strong>@searchedNumber</strong>".
            </div>
        }
    }
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? foundShipment;
    private bool isSearching;
    private bool searchPerformed;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        searchPerformed = false;
        searchedNumber = trackingNumber.Trim();
        StateHasChanged();

        foundShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        isSearching = false;
        searchPerformed = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-info",
        "Pending" => "bg-warning text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

